// The seam through the REAL verifier, against local fixtures only: the
// upstream is a temporary git repository on disk (a local path, no network),
// the recipe and fact bundle are generated by the real draft recorder from it,
// and the runner is the gate's own (its argument check, its child
// environment and its bounded exec). Only the repository address is mapped:
// the runner accepts the https://github.com/ shape and nothing else, so the
// test hands the child the local path at the one place the URL goes, and
// allows the local transport for that child. The mapping lives in this test
// file only; nothing in the package can set it.

var realSeamTags = []string{"v1.0.0", "v1.1.0", "v1.2.0", "v1.3.0"}

// localUpstream builds the fake upstream: four commits (the salt makes the
// commit ids differ between two upstreams of the same content), each with the
// fixture CRD directory, tagged (one annotated tag, to exercise the peeled
// lines of ls-remote).
func localUpstream(t *testing.T, salt string) string {
	t.Helper()
	dir := t.TempDir()
	gitIn(t, dir, "init", "-q")
	writeFile(t, filepath.Join(dir, filepath.FromSlash(obCRD)), []byte(obCRDDoc(obGroup, "v1")))
	writeFile(t, filepath.Join(dir, "README.md"), []byte("readme\n"))
	gitIn(t, dir, "add", "--all")
	for i, tag := range realSeamTags {
		gitIn(t, dir, "commit", "-q", "--allow-empty", "-m", fmt.Sprintf("%s %d", salt, i))
		if tag == "v1.1.0" {
			gitIn(t, dir, "tag", "-a", "-m", "annotated", tag)
		} else {
			gitIn(t, dir, "tag", tag)
		}
	}
	return dir
}

// localRunner is the gate's runner with the repository address mapped to a
// local path: the verifier's exact vector must pass the gate's own check first.
type localRunner struct {
	mu    sync.Mutex
	dir   string
	specs []targetdraft.ExecSpec
	res   []targetdraft.ExecResult
}

func (r *localRunner) Run(ctx context.Context, spec targetdraft.ExecSpec) targetdraft.ExecResult {
	r.mu.Lock()
	r.specs = append(r.specs, spec)
	r.mu.Unlock()
	if !runnerArgvOK(spec.Argv) {
		return targetdraft.ExecResult{Err: os.ErrPermission}
	}
	git := ""
	for _, c := range runnerGitPaths {
		if st, err := os.Stat(c); err == nil && st.Mode().IsRegular() {
			git = c
			break
		}
	}
	if git == "" {
		return targetdraft.ExecResult{Err: os.ErrNotExist}
	}
	argv := append([]string(nil), spec.Argv...)
	argv[len(runnerPrefix)] = r.dir
	env := make([]string, 0, len(spec.Env))
	for _, e := range spec.Env {
		if e == "GIT_ALLOW_PROTOCOL=https" {
			e = "GIT_ALLOW_PROTOCOL=file"
		}
		env = append(env, e)
	}
	home, err := os.MkdirTemp("", "prufyx-localrunner-")
	if err != nil {
		return targetdraft.ExecResult{Err: err}
	}
	defer os.RemoveAll(home)
	res := runnerExec(ctx, git, argv[1:], runnerChildEnv(targetdraft.ExecSpec{Env: env}, home), home)
	r.mu.Lock()
	r.res = append(r.res, res)
	r.mu.Unlock()
	return res
}

func (r *localRunner) calls() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return len(r.specs)
}

// realSeam is a seam fixture on the COMPILED layout (the layout lock forced on
// in a copy). The gate runs on the fixture as it is, then the seam is run on an
// extended head: the same head plus the real recipe directory and the generated
// target of the fake upstream, committed in its own repository. The seam
// options point at that repository and tree. (The gate's own recipe allowance
// is exercised on a fixture of its own, in onboarding_recipes_test.go.)
type realSeam struct {
	*seamFixture
	up     string
	runner *localRunner
	// head2 is the extended head tree.
	head2 Tree
	// seen is the last result of the real verifier.
	seen targetdraft.OnboardingVerifyResult
}

func newRealSeam(t *testing.T) *realSeam {
	t.Helper()
	f := newOnboardingFixture(t)
	up := localUpstream(t, "a")
	src := targetdraft.GitSource{Dir: up}
	in := targetdraft.Input{Slug: obSlug, Name: "Synthetic", Repo: obRepo, Catalog: "cncf", Tags: realSeamTags, Source: src, CollapseDirectories: true}
	res, err := targetdraft.Generate(in)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	rd, err := targetdraft.RecordDraft(in, src, res.A, res.TableRow)
	if err != nil {
		t.Fatalf("record: %v", err)
	}
	ol := DefaultLayout().Onboarding
	if want := targetdraft.CrdVersionsDir + "/target-" + obSlug + ".json"; targetPath(ol, obSlug) != want || targetdraft.RecipesRoot != recipesRoot {
		t.Fatalf("layout and verifier disagree: %s vs %s", targetPath(ol, obSlug), want)
	}
	s := &realSeam{up: up, runner: &localRunner{dir: up}}
	s.seamFixture = seamFixtureOf(t, f)
	// The gate runs once on the fixture itself with the seam's run-time lock
	// off (no seam run, no verifier call); the seam is run below.
	s.gate(func(o *Options) { o.OnboardingAdmissionInProcess = false })
	s.head2 = cloneTree(t, f.head)
	files := map[string][]byte{"recipe.json": rd.Recipe, "facts.bundle": rd.FactsBundle, "report.json": rd.Report, "table-row.json": rd.TableRow, "changelog.md": rd.Changelog}
	if len(rd.Rules) != 0 {
		files["rules.json"] = rd.Rules
	}
	for name, raw := range files {
		writeFile(t, filepath.Join(s.head2.Root, filepath.FromSlash(recipesRoot+obSlug+"/"+name)), raw)
	}
	writeFile(t, filepath.Join(s.head2.Root, filepath.FromSlash(targetPath(ol, obSlug))), rd.Target)
	// The layout is the COMPILED one with only the layout lock forced on: the
	// admission path sets are the ones the gate ships, not test-built.
	want := DefaultLayout().OnboardingAdmission
	want.Enabled = true
	if !reflect.DeepEqual(s.opts.Layout.OnboardingAdmission, want) {
		t.Fatalf("the test layout is not the compiled one: %+v", s.opts.Layout.OnboardingAdmission)
	}
	s.opts.AdmissionRunner = s.runner
	s.opts.AdmissionVerifier = func(in targetdraft.OnboardingVerifyInput) targetdraft.OnboardingVerifyResult {
		res := targetdraft.VerifyOnboarding(in)
		s.mu.Lock()
		s.seen = res
		s.mu.Unlock()
		return res
	}
	return s
}

// seamOn runs only the seam, on the base and a head tree committed in a repository
// of its own (the gate's own report and input are the fixture's). The input's
// changed paths stay the gate's.
func (s *realSeam) seamOn(head Tree) OnboardingAdmissionInput {
	s.t.Helper()
	repo := s.t.TempDir()
	gitIn(s.t, repo, "init", "--bare", "-q")
	base := admissionCommit(s.t, repo, s.f.base, "")
	headSHA := admissionCommit(s.t, repo, head, base)
	gitIn(s.t, repo, "update-ref", admissionBaseRef, base)
	gitIn(s.t, repo, "update-ref", admissionHeadRef, headSHA)
	return s.direct(func(o *Options, in *OnboardingAdmissionInput) {
		g := *o.OnboardingGit
		g.GitDir, g.BaseCommit, g.HeadCommit = repo, base, headSHA
		o.OnboardingGit, o.Head, o.HeadSHA = &g, head, headSHA
		in.BaseSHA, in.GitHeadSHA, in.HeadSHA = base, headSHA, headSHA
	})
}

// The layout flag stays off in the compiled default; the tests turn it on in
// their own copy only.
func TestRealSeamDefaultLayoutStaysOff(t *testing.T) {
	t.Parallel()
	if DefaultLayout().OnboardingAdmission.Enabled {
		t.Fatal("the compiled default layout turned the admission seam on")
	}
}

// Positive: the real verifier, the real recipe and fact bundle, the real
// binding through the gate's runner against a local upstream. The seam hands
// the frozen decision a result that binds to the exact commits, the project and
// the digests of the real change; the frozen checker, given the same change set
// as its path set, finds no verify-pr reason.
func TestRealSeamPositiveEndToEnd(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	in := s.seamOn(s.head2)
	if len(in.SeamRefusals) != 0 || in.VerifyPr == nil {
		t.Fatalf("seam refused: %v (verifier %+v)", in.SeamRefusals, s.seen)
	}
	if s.seen.Mode != targetdraft.OnboardingVerifyMode || s.seen.Outcome != "pass" || !s.seen.BindingVerified || s.seen.RecipeChange != "new" || s.seen.Eligible {
		t.Fatalf("real verifier: %+v", s.seen)
	}
	if s.runner.calls() != 1 {
		t.Fatalf("runner called %d times", s.runner.calls())
	}
	spec := s.runner.specs[0]
	if len(spec.Argv) != len(runnerPrefix)+1+2*len(realSeamTags) || spec.Argv[len(runnerPrefix)] != "https://github.com/"+obOwnerRepo+".git" {
		t.Fatalf("upstream vector %v", spec.Argv)
	}
	if res := s.runner.res[0]; res.Err != nil || res.Exit != 0 || res.TimedOut || len(res.Stdout) == 0 {
		t.Fatalf("local ls-remote: %+v", res)
	}
	v := in.VerifyPr
	if v.Outcome != "pass" || !v.BindingVerified || v.RecipeChange != "new" || v.Eligible || len(v.Slugs) != 1 || v.Slugs[0] != obSlug ||
		v.BaseSHA != in.BaseSHA || v.HeadSHA != in.HeadSHA || !admitValidDigest(v.BindingDigest) || !admitValidDigest(v.ChangedPathsSHA256) {
		t.Fatalf("handed result %+v", v)
	}
	// The frozen checker, with the real change set as its path set.
	paths, err := ChangedPaths(s.f.base, s.head2)
	if err != nil {
		t.Fatal(err)
	}
	in.ChangedPaths = paths
	d := AdmitOnboardingAuto(in)
	if got := verifyReasons(&d); len(got) != 0 {
		t.Fatalf("verify-pr reasons on a real pass: %v (all %v)", got, d.Reasons)
	}
	if d.VerifyPr.ChangedPathsSHA256 != d.PathSetSHA || d.VerifyPr.Outcome != "pass" {
		t.Fatalf("decision binding %+v path set %s", d.VerifyPr, d.PathSetSHA)
	}
	// The compiled path sets accept the whole real change: no path reason of
	// the decision, and the verifier's judged subset and A1's path set agree.
	if got := pathReasons(&d); len(got) != 0 {
		t.Fatalf("path reasons on the compiled layout: %v (all %v)", got, d.Reasons)
	}
	// Nothing here is merge authority: an owner fixture is never admitted.
	if d.Admitted {
		t.Fatal("an owner fixture with no allowlist was admitted")
	}
}

// Negative: a tag of the upstream is not the commit the recipe and the bundle
// name. The real binding refuses; no result is handed on.
func TestRealSeamTagMismatchRefused(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	s.runner.dir = localUpstream(t, "b") // same tags, other commits
	in := s.seamOn(s.head2)
	seamOnly(t, in, AdmitReasonSeamFailed)
	if s.seen.Outcome != "fail" || s.seen.Harness || !containsStr(s.seen.Reasons, "binding-mismatch") {
		t.Fatalf("verifier: %+v", s.seen)
	}
	if s.runner.calls() != 1 {
		t.Fatalf("runner called %d times", s.runner.calls())
	}
}

// Negative: one more changed path than the batch allows. The head commit and
// tree carry it (so the tree checks pass); the real verifier refuses the path
// outside the allowlist before any network use.
func TestRealSeamExtraChangedPathRefused(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	head3 := cloneTree(t, s.head2)
	writeFile(t, filepath.Join(head3.Root, "cli", "knowledge", "unrelated.json"), []byte("{}\n"))
	in := s.seamOn(head3)
	seamOnly(t, in, AdmitReasonSeamFailed)
	if s.seen.Outcome != "fail" || !containsStr(s.seen.Reasons, targetdraft.OnbReasonOutside) {
		t.Fatalf("verifier: %+v", s.seen)
	}
	if s.runner.calls() != 0 {
		t.Fatal("the network was used for a change that failed the local checks")
	}
}

func containsStr(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

// pathReasons are the reasons of the decision that concern the changed paths.
func pathReasons(d *OnboardingAdmission) []string {
	paths := map[string]bool{AdmitReasonPathSet: true, AdmitReasonAllowlistUnset: true, AdmitReasonTrustPath: true, AdmitReasonForbiddenPath: true,
		AdmitReasonPathOutside: true, AdmitReasonBatchPath: true, AdmitReasonProjects: true, AdmitReasonFileModes: true}
	var out []string
	for _, r := range d.Reasons {
		if paths[r] {
			out = append(out, r)
		}
	}
	return out
}

// One negative per path set of the compiled layout: a file outside the exact
// set is refused by the real verifier before any network use, and by the
// frozen checker with the outside-path reason.
func TestRealSeamCompiledPathSetNegatives(t *testing.T) {
	t.Parallel()
	for _, c := range []struct {
		name, path string
	}{
		{"static set", "cli/docs/generated/other.md"},
		{"project set, another file name", recipesRoot + obSlug + "/extra.json"},
		{"project set, a subdirectory", recipesRoot + obSlug + "/sub/recipe.json"},
		{"project set, another project's directory", recipesRoot + "other-project/recipe.json"},
		{"target set, another project's target", targetdraft.CrdVersionsDir + "/target-other-project.json"},
		{"target set, a name that is not a target", targetdraft.CrdVersionsDir + "/extra.json"},
	} {
		t.Run(c.name, func(t *testing.T) {
			t.Parallel()
			s := newRealSeam(t)
			head3 := cloneTree(t, s.head2)
			writeFile(t, filepath.Join(head3.Root, filepath.FromSlash(c.path)), []byte("{}\n"))
			in := s.seamOn(head3)
			seamOnly(t, in, AdmitReasonSeamFailed)
			if s.seen.Outcome != "fail" {
				t.Fatalf("verifier: %+v", s.seen)
			}
			if s.runner.calls() != 0 {
				t.Fatal("the network was used for a change that failed the local checks")
			}
			paths, err := ChangedPaths(s.f.base, head3)
			if err != nil {
				t.Fatal(err)
			}
			in.ChangedPaths = paths
			d := AdmitOnboardingAuto(in)
			if !containsStr(d.Reasons, AdmitReasonPathOutside) {
				t.Fatalf("the checker did not refuse %s: %v", c.path, d.Reasons)
			}
		})
	}
}

// The compiled sets, with each entry removed in turn, no longer cover the real
// change: the positive test is not satisfied by a looser list.
func TestRealSeamCompiledSetsAreNeeded(t *testing.T) {
	t.Parallel()
	s := newRealSeam(t)
	in := s.seamOn(s.head2)
	if len(in.SeamRefusals) != 0 {
		t.Fatalf("seam refused: %v", in.SeamRefusals)
	}
	paths, err := ChangedPaths(s.f.base, s.head2)
	if err != nil {
		t.Fatal(err)
	}
	in.ChangedPaths = paths
	cfg := in.Config
	trimmed := func(list []string, i int) []string {
		return append(append([]string(nil), list[:i]...), list[i+1:]...)
	}
	for i := range cfg.StaticPaths {
		c := in
		c.Config.StaticPaths = trimmed(cfg.StaticPaths, i)
		d := AdmitOnboardingAuto(c)
		if containsStr(paths, cfg.StaticPaths[i]) && !containsStr(d.Reasons, AdmitReasonPathOutside) {
			t.Errorf("dropping static %s from the list still admits the paths", cfg.StaticPaths[i])
		}
	}
	for i := range cfg.ProjectPaths {
		c := in
		c.Config.ProjectPaths = trimmed(cfg.ProjectPaths, i)
		if !containsStr(paths, strings.ReplaceAll(cfg.ProjectPaths[i], "{slug}", obSlug)) {
			continue // a recipe file this fixture does not carry
		}
		if d := AdmitOnboardingAuto(c); !containsStr(d.Reasons, AdmitReasonPathOutside) {
			t.Errorf("dropping project path %s still admits the paths", cfg.ProjectPaths[i])
		}
	}
	c := in
	c.Config.TargetPath = ""
	if d := AdmitOnboardingAuto(c); !containsStr(d.Reasons, AdmitReasonProjects) {
		t.Error("an unset target path still admits")
	}
}
